import { createSupabaseBrowserClient, isLiveSupabase } from './supabase/client';
import type {
  MonitoredSite,
  MonitoredSiteWithLatestCheck,
  MonitorCheck,
  Incident,
  AlertChannel,
  CreateSiteInput,
  CreateAlertChannelInput,
} from '@pingwatch/shared';

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8080';

export function getArtifactUrl(path: string | null | undefined): string | null {
  if (!path) return null;
  return `${API_BASE_URL}/artifacts/${path.split('/').map(encodeURIComponent).join('/')}`;
}

async function getAuthToken(): Promise<string> {
  const supabase = createSupabaseBrowserClient();
  const { data: { session } } = await supabase.auth.getSession();

  if (session?.access_token) {
    return session.access_token;
  }

  // Check localStorage for simulated session in demo mode
  if (typeof window !== 'undefined') {
    const localToken = localStorage.getItem('pingwatch_demo_token');
    if (localToken) return localToken;
  }

  return 'demo-bearer-token';
}

async function request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
  const token = await getAuthToken();
  const headers = new Headers(options.headers || {});
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('Authorization', `Bearer ${token}`);
  }

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    ...options,
    headers,
  });

  if (!response.ok) {
    let errorMessage = `HTTP Error ${response.status}: ${response.statusText}`;
    try {
      const errorJson = await response.json();
      if (errorJson.error) {
        errorMessage = errorJson.error;
      }
    } catch {
      // ignore
    }
    throw new Error(errorMessage);
  }

  if (response.status === 204) {
    return {} as T;
  }

  return response.json() as Promise<T>;
}

export const api = {
  // Sites
  getSites: () => request<MonitoredSiteWithLatestCheck[]>('/sites'),
  createSite: (input: CreateSiteInput) =>
    request<MonitoredSite>('/sites', {
      method: 'POST',
      body: JSON.stringify(input),
    }),
  deleteSite: (siteId: string) =>
    request<{ success: boolean }>(`/sites/${siteId}`, {
      method: 'DELETE',
    }),
  runSiteNow: (siteId: string) =>
    request<{ status: string }>(`/sites/${siteId}/run-now`, {
      method: 'POST',
    }),

  // Checks
  getSiteChecks: (siteId: string, limit: number = 50, offset: number = 0) =>
    request<MonitorCheck[]>(`/sites/${siteId}/checks?limit=${limit}&offset=${offset}`),

  // Incidents
  getSiteIncidents: (siteId: string) =>
    request<Incident[]>(`/sites/${siteId}/incidents`),

  // Alert Channels
  getAlertChannels: (siteId?: string) =>
    request<AlertChannel[]>(
      siteId ? `/alert-channels?site_id=${siteId}` : '/alert-channels'
    ),
  createAlertChannel: (input: CreateAlertChannelInput) =>
    request<AlertChannel>('/alert-channels', {
      method: 'POST',
      body: JSON.stringify(input),
    }),
  deleteAlertChannel: (channelId: string) =>
    request<{ success: boolean }>(`/alert-channels/${channelId}`, {
      method: 'DELETE',
    }),
};
